export interface ICatalogButton {
	/** Command id: an existing command, or `saengine.catalog.<tab>.<slug>` for a planned feature. */
	readonly id: string;
	readonly planned: boolean;
	readonly label: string;
	readonly description: string;
	readonly size: 'large' | 'small';
	/** A Codicon name. */
	readonly icon: string;
}

export interface ICatalogGroup {
	readonly tab: string;
	/** The menu group, `<order>_<key>`; the key carries the label. */
	readonly group: string;
	readonly key: string;
	readonly label: string;
	readonly part: string;
	readonly buttons: readonly ICatalogButton[];
}

